    const hadOptionFocus=document.activeElement?.matches?.('[data-mm-pick],[data-mm-option-explain],[data-mm-option-reason]')&&w.contains(document.activeElement),expanded=explanatory(w)?new Set([...w.querySelectorAll('[data-mm-option-explain][aria-expanded=true]')].map(node=>node.dataset.mmOptionExplain)):new Set();
