    w.querySelectorAll('[data-mm-pick]').forEach(option=>{const matches=window.UKI18n?UKI18n.matches(option.dataset.mmLabel,query):option.dataset.mmLabel.toLocaleLowerCase().includes(query),row=explanatory(w)?option.closest('[data-mm-option-row]'):option;row.hidden=!matches;if(matches)count++;});
    w.querySelectorAll('.mm-combo-group').forEach(group=>{let next=group.nextElementSibling,hasVisible=false;while(next&&!next.classList.contains('mm-combo-group')){if(next.matches('[data-mm-pick]:not([hidden]),[data-mm-option-row]:not([hidden])'))hasVisible=true;next=next.nextElementSibling;}group.hidden=!hasVisible;});
    w.querySelector('.mm-combo-empty').hidden=count>0;
