  function viewport(){const v=window.visualViewport;return{left:v?.offsetLeft||0,top:v?.offsetTop||0,width:v?.width||window.innerWidth,height:v?.height||window.innerHeight}}
  function updateViewport(){const v=viewport();document.documentElement.style.setProperty('--mm-viewport-height',v.height+'px');document.documentElement.style.setProperty('--mm-viewport-top',v.top+'px');if(activeCombo)position(activeCombo)}
  function position(w){
    if(!w?.isConnected){closeAll();return}
    const p=popup(w),rect=trigger(w).getBoundingClientRect(),v=viewport(),gap=6,minTop=v.top+8,maxBottom=v.top+v.height-8;
    const outside=rect.bottom<v.top||rect.top>maxBottom,typing=document.activeElement===search(w);
    if(outside&&!typing){closeAll();return}
    const below=maxBottom-rect.bottom-gap,above=rect.top-minTop-gap,up=below<180&&above>below,space=Math.max(0,up?above:below);
    const floating=outside||space<100,height=Math.min(340,floating?Math.max(0,v.height-16):space),width=Math.min(Math.max(rect.width,180),Math.max(0,v.width-16));
    const left=Math.max(v.left+8,Math.min(rect.left,v.left+v.width-width-8));
    Object.assign(p.style,{position:'fixed',left:left+'px',width:width+'px',maxHeight:height+'px',top:floating?minTop+'px':up?'auto':Math.max(minTop,rect.bottom+gap)+'px',bottom:!floating&&up?Math.max(0,window.innerHeight-rect.top+gap)+'px':'auto'});
  }

  function closeCombo(w,{restore=false}={}){if(!w)return;const p=popup(w);if(p)p.hidden=true;trigger(w)?.setAttribute('aria-expanded','false');if(activeCombo===w)activeCombo=null;if(editable(document.activeElement)&&w.contains(document.activeElement))document.activeElement.blur();if(restore)safeFocus(trigger(w))}
  function closeAll(except){document.querySelectorAll('[data-mm-combo]').forEach(w=>{if(w!==except)closeCombo(w)})}
  function open(node,{keyboard=false,last=false}={}){const w=wrapper(node);if(!w||trigger(w)?.disabled)return;closeAll(w);sync(w);const input=search(w);input.value='';filterOptions(w);activeCombo=w;popup(w).hidden=false;trigger(w).setAttribute('aria-expanded','true');if(editable(document.activeElement))document.activeElement.blur();safeFocus(trigger(w));position(w);if(keyboard){const available=optionTargets(w);safeFocus(last?available.at(-1):available[0])}}
  window.MMWidgets={combo(name,label,options,value='',placeholder='Select an option',settings={}){
    const key='mm-combo-'+(++serial),selected=options.find(o=>string(o.value)===string(value)),explain=settings?.explain===true,caption=label.replace(/\*/g,'').trim(),labelId=key+'-label';
    const start=explain?`<span class="mm-combo-label mm-combo-explain-label" role="group" aria-labelledby="${labelId}"><span id="${labelId}" class="mm-combo-caption">${esc(label)}</span>`:`<label class="mm-combo-label">${esc(label)}`;
    return start+`<span class="mm-combo" data-mm-combo${explain?' data-mm-explain-options="true"':''} data-mm-placeholder="${esc(placeholder)}"><input type="hidden" name="${esc(name)}" value="${esc(value)}"><button id="${key}" type="button" class="mm-combo-input mm-combo-trigger" data-mm-toggle data-mm-trigger role="combobox"${explain?` aria-labelledby="${labelId}"`:''} aria-haspopup="${explain?'dialog':'listbox'}" aria-expanded="false" aria-controls="${key}-${explain?'popup':'options'}"><span data-mm-value-label${explain?` id="${key}-value"`:''} class="${selected?'':'mm-combo-placeholder'}">${esc(selected?.label||placeholder)}</span><span aria-hidden="true" class="mm-combo-chevron">⌄</span></button><span class="mm-combo-list" id="${key}-popup"${explain?` role="dialog" aria-modal="false" aria-labelledby="${labelId}"`:''} hidden><span class="mm-combo-search"><input type="search" data-mm-search autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="Search ${esc(caption)}" placeholder="Search..."></span><span class="mm-combo-options" id="${key}-options" role="${explain?'group':'listbox'}" aria-label="${esc(caption)}">${optionMarkup(options,value,explain,key)}</span></span></span>`+(explain?'</span>':'</label>');
  },setValue,setOptions,sync,open,closeAll};
  window.addEventListener('click',e=>{const action=e.target.closest?.('button,a[href],[role=button]');if(action)lastActivator=action;const w=wrapper(e.target);if(!w){closeAll();return}const explainButton=e.target.closest('[data-mm-option-explain]');if(explainButton&&explanatory(w)){e.preventDefault();e.stopPropagation();const panel=document.getElementById(explainButton.getAttribute('aria-controls'));if(panel&&w.contains(panel)){panel.hidden=!panel.hidden;explainButton.setAttribute('aria-expanded',string(!panel.hidden));position(w);}return}const choice=e.target.closest('[data-mm-pick]');if(choice){if(choice.disabled)return;e.preventDefault();closeCombo(w,{restore:true});setValue(w,choice.dataset.mmPick,{emit:true});return}if(e.target.closest('[data-mm-trigger]')){e.preventDefault();if(popup(w).hidden)open(w);else closeCombo(w,{restore:true})}},true);
  window.addEventListener('change',e=>{if(e.target.matches?.('[data-mm-combo] input[type=hidden][name]'))sync(e.target)},true);
  document.addEventListener('input',e=>{if(e.target.matches('[data-mm-search]')){const w=wrapper(e.target);filterOptions(w);position(w)}});
  window.addEventListener('keydown',e=>{let w=wrapper(e.target)||activeCombo;if(e.key==='Escape'&&activeCombo){e.preventDefault();e.stopImmediatePropagation();closeCombo(activeCombo,{restore:true});return}if(!w)return;const available=()=>optionTargets(w);if(e.target.matches('[data-mm-trigger]')&&['ArrowDown','ArrowUp','Enter',' '].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(!popup(w).hidden&&['Enter',' '].includes(e.key))closeCombo(w,{restore:true});else open(w,{keyboard:true,last:e.key==='ArrowUp'});return}if((!popup(w)?.hidden&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&!editable(e.target))||(e.target.matches('[data-mm-search]')&&['ArrowDown','ArrowUp'].includes(e.key))){const items=available(),i=items.indexOf(e.target);if(items.length){e.preventDefault();e.stopImmediatePropagation();const next=e.key==='Home'?0:e.key==='End'?items.length-1:i<0?(e.key==='ArrowUp'?items.length-1:0):(i+(e.key==='ArrowUp'?-1:1)+items.length)%items.length;safeFocus(items[next]);}return}if(e.key==='Tab'&&!popup(w)?.hidden){e.preventDefault();e.stopImmediatePropagation();const items=[search(w),...optionTargets(w,true)].filter(visible),i=items.indexOf(e.target),next=i+(e.shiftKey?-1:1);if(next>=0&&next<items.length){const target=items[next];if(editable(target))target.focus({preventScroll:true});else safeFocus(target)}else{closeCombo(w);safeFocus(trigger(w))}return}},true);
  document.addEventListener('focusin',e=>{if(activeCombo&&!activeCombo.contains(e.target))closeAll()});
  window.addEventListener('resize',updateViewport);
  window.visualViewport?.addEventListener('resize',updateViewport);
  window.visualViewport?.addEventListener('scroll',updateViewport);updateViewport();
  document.addEventListener('scroll',e=>{if(activeCombo&&!popup(activeCombo).contains(e.target))position(activeCombo)},true);

  function lockPage(){const present=!!document.querySelector('.modal-bg');if(present&&lockedOverflow===null){lockedOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}else if(!present&&lockedOverflow!==null){document.body.style.overflow=lockedOverflow;lockedOverflow=null}}
  function dismiss(bg,{restore=true}={}){if(!bg?.isConnected)return;closeAll();bg.remove();modalOpen=!!document.querySelector('.modal-bg');lockPage();if(restore&&!modalOpen)safeFocus(returnFocus)}
  closeModal=function(options={}){const backgrounds=[...document.querySelectorAll('.modal-bg')];if(!backgrounds.length)return;closeAll();backgrounds.forEach(bg=>bg.remove());modalOpen=false;lockPage();if(options.restore!==false)safeFocus(returnFocus)};
  showModal=function(title,body,submit,onSubmit){const prior=returnFocus,candidate=lastActivator?.isConnected?lastActivator:document.activeElement;closeAll();closeModal({restore:false});returnFocus=candidate?.isConnected&&!editable(candidate)?candidate:prior?.isConnected&&!editable(prior)?prior:null;if(editable(document.activeElement))document.activeElement.blur();modalOpen=true;const modalId='mm-dialog-'+(++serial);document.body.insertAdjacentHTML('beforeend',`<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="${modalId}"><header class="modal-head"><h2 id="${modalId}">${title}</h2><button type="button" class="icon-btn" id="modal-close" aria-label="Close">×</button></header><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn" id="modal-cancel">Cancel</button><button type="button" class="btn primary" id="modal-submit">${esc(submit||'Save')}</button></footer></section></div>`);const bg=document.querySelector('.modal-bg'),button=bg.querySelector('#modal-submit'),cancel=()=>dismiss(bg);let pending=false;bg.querySelector('#modal-close').onclick=bg.querySelector('#modal-cancel').onclick=cancel;bg.addEventListener('click',e=>{if(e.target===bg)cancel()});const previousDescription=button.getAttribute('aria-describedby');function clearSaveError(){bg.querySelector('[data-modal-save-error]')?.remove();if(previousDescription==null)button.removeAttribute('aria-describedby');else button.setAttribute('aria-describedby',previousDescription);}function saveError(err){if(!bg.isConnected)return;let node=bg.querySelector('[data-modal-save-error]');if(!node){node=document.createElement('p');node.dataset.modalSaveError='';node.id=modalId+'-save-error';node.className='modal-save-error';node.setAttribute('role','alert');bg.querySelector('.modal-foot').prepend(node);}node.textContent=(window.UKI18n?.language==='ko'?'저장하지 못했습니다. ':'Unable to save. ')+String(err?.message||err);button.setAttribute('aria-describedby',[previousDescription,node.id].filter(Boolean).join(' '));}button.onclick=()=>{if(pending||!bg.isConnected)return;clearSaveError();let result;try{result=onSubmit?.()}catch(err){saveError(err);return}if(result&&typeof result.then==='function'){pending=true;button.disabled=true;result.then(value=>{if(value!==false)dismiss(bg)}).catch(saveError).finally(()=>{pending=false;if(button.isConnected)button.disabled=false})}else if(result!==false)dismiss(bg)};for(const event of ['input','change'])bg.querySelector('#modal-form')?.addEventListener(event,clearSaveError);bg.querySelector('#modal-form')?.addEventListener('submit',e=>{e.preventDefault();button.click()});lockPage();safeFocus(bg.querySelector('#modal-close'));};
  formModal=function(title,fields,onSubmit,submit='Save Changes'){showModal(title,`<form id="modal-form" class="form two">${fields}</form>`,submit,()=>{const form=document.querySelector('#modal-form');if(!form.reportValidity())return false;return onSubmit(Object.fromEntries(new FormData(form)))})};
  document.addEventListener('keydown',e=>{const bg=[...document.querySelectorAll('.modal-bg')].filter(x=>!x.inert&&!x.hasAttribute('inert')).at(-1);if(!bg)return;if(e.key==='Escape'){e.preventDefault();dismiss(bg)}if(e.key==='Tab'){const focus=[...bg.querySelectorAll('input:not([type=hidden]),select,textarea,button,a[href],[contenteditable=true]')].filter(x=>!x.disabled&&!x.hidden&&x.tabIndex!==-1&&!x.closest('[hidden],[inert]')&&getComputedStyle(x).display!=='none'&&getComputedStyle(x).visibility!=='hidden');if(!focus.length)return;if(!bg.contains(document.activeElement)){e.preventDefault();safeFocus(focus[0])}else if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1).focus({preventScroll:true})}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();safeFocus(focus[0])}}});
